package fr.mairie.dossiers.web;

import fr.mairie.dossiers.data.DatasetLoader;
import fr.mairie.dossiers.service.DossierService;

import javax.servlet.ServletContext;
import javax.servlet.ServletContextEvent;
import javax.servlet.ServletContextListener;
import java.io.IOException;
import java.time.Clock;
import java.time.LocalDate;
import java.time.ZoneOffset;
import java.time.format.DateTimeParseException;

/**
 * Charge le jeu de données au démarrage et publie le service métier, avec
 * l'horloge figée par la variable d'environnement {@value #FROZEN_DATE}
 * (aaaa-mm-jj).
 */
public class DossierServiceListener implements ServletContextListener {

    static final String FROZEN_DATE = "FROZEN_DATE";

    private static final String ATTRIBUTE = DossierService.class.getName();

    public void contextInitialized(ServletContextEvent event) {
        try {
            event.getServletContext().setAttribute(ATTRIBUTE,
                    new DossierService(DatasetLoader.load(), frozenClock(System.getenv(FROZEN_DATE))));
        } catch (IOException e) {
            throw new IllegalStateException("Cannot load the dataset", e);
        }
    }

    public void contextDestroyed(ServletContextEvent event) {
        event.getServletContext().removeAttribute(ATTRIBUTE);
    }

    public static DossierService serviceOf(ServletContext context) {
        return (DossierService) context.getAttribute(ATTRIBUTE);
    }

    /** Horloge arrêtée à minuit UTC du jour donné. Sans ce jour, le legacy ne démarre pas. */
    private static Clock frozenClock(String date) {
        if (date == null || date.isEmpty()) {
            throw new IllegalStateException(FROZEN_DATE + " is not set");
        }
        try {
            return Clock.fixed(LocalDate.parse(date).atStartOfDay(ZoneOffset.UTC).toInstant(), ZoneOffset.UTC);
        } catch (DateTimeParseException e) {
            throw new IllegalStateException(FROZEN_DATE + " is not an ISO date (yyyy-mm-dd): " + date, e);
        }
    }
}
package fr.mairie.dossiers.web;

import fr.mairie.dossiers.model.Dossier;
import fr.mairie.dossiers.model.Status;

/**
 * Dossier prêt à afficher par les JSP des écrans 2 et 3 : valeurs en lecture
 * seule (dates en jj/mm/aaaa), statut et verrou des champs de la fiche.
 */
public class DossierView {

    private final Dossier dossier;

    public DossierView(Dossier dossier) {
        this.dossier = dossier;
    }

    public String getNumber() {
        return dossier.getNumber();
    }

    /** Récapitulatif de l'écran 3. */
    public String getApplicant() {
        return dossier.getApplicant();
    }

    /** Récapitulatif de l'écran 3. */
    public String getSubject() {
        return dossier.getSubject();
    }

    /**
     * Nom du statut ({@code BROUILLON}, {@code EN_INSTRUCTION}, {@code REMIS}),
     * comparé par {@code <logic:equal>} dans les JSP.
     */
    public String getStatus() {
        return dossier.getStatus().name();
    }

    /**
     * Lien « Remise » sur la fiche : statut {@code EN_INSTRUCTION} ou
     * {@code REMIS}, comme le dit la spec de l'écran 2.
     */
    public boolean isSubmissionLinked() {
        Status status = dossier.getStatus();
        return status == Status.EN_INSTRUCTION || status == Status.REMIS;
    }

    public String getStatusLabel() {
        return dossier.getStatus().getLabel();
    }

    public String getFiledOn() {
        return ScreenDate.FORMAT.format(dossier.getFiledOn());
    }

    /** Date de remise en jj/mm/aaaa, {@code null} si le dossier n'est pas remis. */
    public String getSubmittedOn() {
        return dossier.getSubmittedOn() == null ? null : ScreenDate.FORMAT.format(dossier.getSubmittedOn());
    }

    public boolean isApplicantLocked() {
        return dossier.getStatus().isApplicantLocked();
    }

    public boolean isSubjectLocked() {
        return dossier.getStatus().isSubjectLocked();
    }

    /** Bouton « Enregistrer » et {@code Ctrl+S} présents. */
    public boolean isEditable() {
        return dossier.getStatus().isEditable();
    }
}
package fr.mairie.dossiers.web;

import fr.mairie.dossiers.service.RefusedSubmissionException;
import fr.mairie.dossiers.service.UnknownDossierException;
import org.apache.struts.action.Action;
import org.apache.struts.action.ActionForm;
import org.apache.struts.action.ActionForward;
import org.apache.struts.action.ActionMapping;
import org.apache.struts.action.ActionRedirect;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Écran 3, bouton « Remettre » : remet le dossier, sans confirmation, puis
 * revient sur l'écran de remise. Une remise refusée par le service métier
 * (dossier pas {@code EN_INSTRUCTION}) reçoit 409. Un {@code GET} reçoit 405 :
 * un lien suivi ou préchargé ne doit pas remettre un dossier.
 */
public class RemiseAction extends Action {

    @Override
    public ActionForward execute(ActionMapping mapping, ActionForm actionForm,
                                 HttpServletRequest request, HttpServletResponse response)
            throws IOException {
        if (!"POST".equals(request.getMethod())) {
            response.setHeader("Allow", "POST");
            response.sendError(HttpServletResponse.SC_METHOD_NOT_ALLOWED);
            return null;
        }
        DossierForm form = (DossierForm) actionForm;
        try {
            DossierServiceListener.serviceOf(servlet.getServletContext()).submit(form.getNumber());
        } catch (UnknownDossierException e) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND);
            return null;
        } catch (RefusedSubmissionException e) {
            response.sendError(HttpServletResponse.SC_CONFLICT, e.getMessage());
            return null;
        }
        ActionRedirect redirect = new ActionRedirect(mapping.findForward("submitted"));
        redirect.addParameter("number", form.getNumber());
        return redirect;
    }
}
package fr.mairie.dossiers.web;

import fr.mairie.dossiers.service.LockedFieldException;
import fr.mairie.dossiers.service.UnknownDossierException;
import org.apache.struts.action.Action;
import org.apache.struts.action.ActionForm;
import org.apache.struts.action.ActionForward;
import org.apache.struts.action.ActionMapping;
import org.apache.struts.action.ActionRedirect;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Écran 2 : enregistre le demandeur et l'objet, puis revient sur la fiche.
 * La saisie arrive ici déjà acceptée par {@code validation.xml}. Le verrou du
 * statut est appliqué par le service métier : une requête forgée qui change
 * un champ verrouillé reçoit 409 et rien n'est enregistré.
 */
public class SaveDossierAction extends Action {

    @Override
    public ActionForward execute(ActionMapping mapping, ActionForm actionForm,
                                 HttpServletRequest request, HttpServletResponse response)
            throws IOException {
        DossierForm form = (DossierForm) actionForm;
        try {
            DossierServiceListener.serviceOf(servlet.getServletContext())
                    .update(form.getNumber(), form.getApplicant(), form.getSubject());
        } catch (UnknownDossierException e) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND);
            return null;
        } catch (LockedFieldException e) {
            response.sendError(HttpServletResponse.SC_CONFLICT, e.getMessage());
            return null;
        }
        ActionRedirect redirect = new ActionRedirect(mapping.findForward("saved"));
        redirect.addParameter("number", form.getNumber());
        return redirect;
    }
}
package fr.mairie.dossiers.web;

import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;

/** Format des dates saisies et affichées sur les écrans : jj/mm/aaaa. */
final class ScreenDate {

    static final DateTimeFormatter FORMAT =
            DateTimeFormatter.ofPattern("dd/MM/uuuu").withResolverStyle(ResolverStyle.STRICT);

    private ScreenDate() {
    }

    /** Date saisie, ou {@code null} si elle est vide ou mal formée. */
    static LocalDate parseOrNull(String value) {
        if (value == null || value.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(value, FORMAT);
        } catch (DateTimeParseException e) {
            return null;
        }
    }
}
package fr.mairie.dossiers.web;

import fr.mairie.dossiers.model.Dossier;
import fr.mairie.dossiers.model.SearchCriteria;
import fr.mairie.dossiers.model.Status;
import org.apache.struts.action.Action;
import org.apache.struts.action.ActionForm;
import org.apache.struts.action.ActionForward;
import org.apache.struts.action.ActionMapping;

import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.util.ArrayList;
import java.util.List;

/** Écran 1 : lance la recherche et place les résultats dans la requête. */
public class SearchAction extends Action {

    public static final String RESULTS = "results";

    @Override
    public ActionForward execute(ActionMapping mapping, ActionForm actionForm,
                                 HttpServletRequest request, HttpServletResponse response) {
        SearchForm form = (SearchForm) actionForm;
        SearchCriteria criteria = new SearchCriteria(
                blankToNull(form.getNumber()),
                blankToNull(form.getApplicant()),
                parseStatus(form.getStatus()),
                // Une date mal formée n'arrive pas ici : validation.xml la
                // refuse avant l'action. Elle serait ignorée sinon.
                ScreenDate.parseOrNull(form.getFiledFrom()),
                ScreenDate.parseOrNull(form.getFiledTo()));

        List<SearchResultRow> rows = new ArrayList<SearchResultRow>();
        for (Dossier dossier : DossierServiceListener.serviceOf(servlet.getServletContext()).search(criteria)) {
            rows.add(new SearchResultRow(dossier));
        }
        request.setAttribute(RESULTS, rows);
        return mapping.findForward("success");
    }

    private static String blankToNull(String value) {
        return value == null || value.isEmpty() ? null : value;
    }

    /** « Tous » (valeur vide) ou inconnu : pas de critère de statut. */
    private static Status parseStatus(String value) {
        if (blankToNull(value) == null) {
            return null;
        }
        try {
            return Status.valueOf(value);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }
}
package fr.mairie.dossiers.web;

import org.apache.struts.validator.ValidatorForm;

import java.time.LocalDate;

/** Formulaire de l'écran 1. */
public class SearchForm extends ValidatorForm {

    private String number;
    private String applicant;
    private String status;
    private String filedFrom;
    private String filedTo;

    public String getNumber() {
        return number;
    }

    public void setNumber(String number) {
        this.number = number;
    }

    public String getApplicant() {
        return applicant;
    }

    public void setApplicant(String applicant) {
        this.applicant = applicant;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getFiledFrom() {
        return filedFrom;
    }

    public void setFiledFrom(String filedFrom) {
        this.filedFrom = filedFrom;
    }

    public String getFiledTo() {
        return filedTo;
    }

    public void setFiledTo(String filedTo) {
        this.filedTo = filedTo;
    }

    /**
     * Clé aaaammjj de « Déposé du », lue par la règle {@code validwhen} de
     * {@code validation.xml}, qui compare les entiers mais pas les dates.
     */
    public String getFiledFromKey() {
        return sortableKey(filedFrom);
    }

    /** Clé aaaammjj de « Déposé au » : voir {@link #getFiledFromKey()}. */
    public String getFiledToKey() {
        return sortableKey(filedTo);
    }

    /** {@code null} si la date est vide ou mal formée. */
    private static String sortableKey(String value) {
        LocalDate date = ScreenDate.parseOrNull(value);
        if (date == null) {
            return null;
        }
        return String.format("%04d%02d%02d", date.getYear(), date.getMonthValue(), date.getDayOfMonth());
    }
}
