package fr.mairie.dossiers.model;

/**
 * Statut d'un dossier, avec le verrou qu'il pose sur les champs modifiables
 * de la fiche.
 */
public enum Status {
    BROUILLON("Brouillon", false, false),
    EN_INSTRUCTION("En instruction", true, false),
    REMIS("Remis", true, true);

    private final String label;
    private final boolean applicantLocked;
    private final boolean subjectLocked;

    Status(String label, boolean applicantLocked, boolean subjectLocked) {
        this.label = label;
        this.applicantLocked = applicantLocked;
        this.subjectLocked = subjectLocked;
    }

    public boolean isApplicantLocked() {
        return applicantLocked;
    }

    public boolean isSubjectLocked() {
        return subjectLocked;
    }

    /** Vrai si au moins un champ reste modifiable : la fiche peut être enregistrée. */
    public boolean isEditable() {
        return !applicantLocked || !subjectLocked;
    }

    public String getLabel() {
        return label;
    }
}
package fr.mairie.dossiers.data;

import com.fasterxml.jackson.databind.ObjectMapper;
import fr.mairie.dossiers.model.Dossier;
import fr.mairie.dossiers.model.Status;

import java.io.IOException;
import java.io.InputStream;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Lit le jeu de données fixe ({@code dossiers.json}, dans le classpath) au
 * démarrage. Rien n'est persisté : un redémarrage remet le jeu à zéro.
 */
public final class DatasetLoader {

    private static final String RESOURCE = "/dossiers.json";

    private DatasetLoader() {
    }

    public static List<Dossier> load() throws IOException {
        InputStream input = DatasetLoader.class.getResourceAsStream(RESOURCE);
        if (input == null) {
            throw new IOException("Dataset not found in classpath: " + RESOURCE);
        }
        try {
            DatasetFile file = new ObjectMapper().readValue(input, DatasetFile.class);
            List<Dossier> dossiers = new ArrayList<Dossier>();
            for (DossierRecord record : file.dossiers) {
                dossiers.add(new Dossier(
                        record.number,
                        record.applicant,
                        record.subject,
                        Status.valueOf(record.status),
                        LocalDate.parse(record.filedOn),
                        record.submittedOn == null ? null : LocalDate.parse(record.submittedOn)));
            }
            return dossiers;
        } finally {
            input.close();
        }
    }

    /** Forme du fichier. */
    static class DatasetFile {
        public List<DossierRecord> dossiers;
        public Map<String, List<String>> groups;
    }

    static class DossierRecord {
        public String number;
        public String applicant;
        public String subject;
        public String status;
        public String filedOn;
        public String submittedOn;
    }
}
