package fr.mairie.dossiers.api;

import javax.servlet.Filter;
import javax.servlet.FilterChain;
import javax.servlet.FilterConfig;
import javax.servlet.ServletException;
import javax.servlet.ServletRequest;
import javax.servlet.ServletResponse;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;

/**
 * Filtre par port : refuse (403) toute requête vers l'API interne qui
 * n'arrive pas par le port de l'API interne (paramètre {@code port}, 8081).
 */
public class InternalApiPortFilter implements Filter {

    private int port;

    public void init(FilterConfig config) throws ServletException {
        String value = config.getInitParameter("port");
        try {
            port = Integer.parseInt(value);
        } catch (NumberFormatException e) {
            throw new ServletException("Internal API port is not a number: " + value, e);
        }
    }

    public void doFilter(ServletRequest request, ServletResponse response, FilterChain chain)
            throws IOException, ServletException {
        if (request.getLocalPort() != port) {
            ((HttpServletResponse) response).sendError(HttpServletResponse.SC_FORBIDDEN);
            return;
        }
        chain.doFilter(request, response);
    }

    public void destroy() {
    }
}
package fr.mairie.dossiers.api;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import fr.mairie.dossiers.model.Dossier;
import fr.mairie.dossiers.model.SearchCriteria;
import fr.mairie.dossiers.model.Status;
import fr.mairie.dossiers.service.DossierService;
import fr.mairie.dossiers.service.LockedFieldException;
import fr.mairie.dossiers.service.RefusedSubmissionException;
import fr.mairie.dossiers.service.UnknownDossierException;
import fr.mairie.dossiers.web.DossierServiceListener;

import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * API interne JSON du legacy, servie sous {@code /api} par le port 8081
 * seulement (voir {@link InternalApiPortFilter}). Elle délègue au service
 * métier, qui applique les règles métier.
 */
public class InternalApiServlet extends HttpServlet {

    private static final String DOSSIERS = "/dossiers";
    private static final Pattern DOSSIER = Pattern.compile("^/dossiers/([^/]+)$");
    private static final Pattern SUBMISSION = Pattern.compile("^/dossiers/([^/]+)/remise$");

    private static final ObjectMapper JSON = new ObjectMapper();

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        if (DOSSIERS.equals(pathOf(request))) {
            List<Map<String, Object>> dossiers = new ArrayList<Map<String, Object>>();
            for (Dossier found : service().search(criteriaOf(request))) {
                dossiers.add(toJson(found));
            }
            Map<String, Object> json = new LinkedHashMap<String, Object>();
            json.put("dossiers", dossiers);
            writeJson(response, HttpServletResponse.SC_OK, json);
            return;
        }
        Matcher dossier = DOSSIER.matcher(pathOf(request));
        if (dossier.matches()) {
            try {
                writeJson(response, HttpServletResponse.SC_OK, toJson(service().read(dossier.group(1))));
            } catch (UnknownDossierException e) {
                writeError(response, HttpServletResponse.SC_NOT_FOUND, e.getMessage());
            }
            return;
        }
        writeError(response, HttpServletResponse.SC_NOT_FOUND, "Unknown endpoint");
    }

    /**
     * Modifier : corps {@code {"applicant": "…", "subject": "…"}}, les deux
     * champs en chaînes, vides acceptées. Le service métier applique le
     * verrou du statut : un champ verrouillé qui change reçoit 409 et rien
     * n'est enregistré.
     */
    @Override
    protected void doPut(HttpServletRequest request, HttpServletResponse response) throws IOException {
        Matcher dossier = DOSSIER.matcher(pathOf(request));
        if (!dossier.matches()) {
            writeError(response, HttpServletResponse.SC_NOT_FOUND, "Unknown endpoint");
            return;
        }
        JsonNode body;
        try {
            body = JSON.readTree(request.getInputStream());
        } catch (JsonProcessingException e) {
            writeError(response, HttpServletResponse.SC_BAD_REQUEST, "Body is not JSON");
            return;
        }
        if (body == null || !body.path("applicant").isTextual() || !body.path("subject").isTextual()) {
            writeError(response, HttpServletResponse.SC_BAD_REQUEST,
                    "Body must be an object with string fields applicant and subject");
            return;
        }
        try {
            Dossier updated = service().update(dossier.group(1),
                    body.get("applicant").textValue(), body.get("subject").textValue());
            writeJson(response, HttpServletResponse.SC_OK, toJson(updated));
        } catch (UnknownDossierException e) {
            writeError(response, HttpServletResponse.SC_NOT_FOUND, e.getMessage());
        } catch (LockedFieldException e) {
            writeError(response, HttpServletResponse.SC_CONFLICT, e.getMessage());
        }
    }

    /**
     * Remettre : sans corps. Le service métier refuse (409) tout dossier qui
     * n'est pas {@code EN_INSTRUCTION}.
     */
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        Matcher submission = SUBMISSION.matcher(pathOf(request));
        if (!submission.matches()) {
            writeError(response, HttpServletResponse.SC_NOT_FOUND, "Unknown endpoint");
            return;
        }
        try {
            writeJson(response, HttpServletResponse.SC_OK, toJson(service().submit(submission.group(1))));
        } catch (UnknownDossierException e) {
            writeError(response, HttpServletResponse.SC_NOT_FOUND, e.getMessage());
        } catch (RefusedSubmissionException e) {
            writeError(response, HttpServletResponse.SC_CONFLICT, e.getMessage());
        }
    }

    private DossierService service() {
        return DossierServiceListener.serviceOf(getServletContext());
    }

    /**
     * Mêmes critères que l'écran 1, sans les règles de {@code validation.xml} :
     * un paramètre vide ou absent n'est pas un critère, et, comme dans
     * {@code SearchAction}, un statut inconnu ou une date mal formée
     * (aaaa-mm-jj attendu) est ignoré au lieu d'être refusé.
     */
    private static SearchCriteria criteriaOf(HttpServletRequest request) {
        return new SearchCriteria(
                blankToNull(request.getParameter("number")),
                blankToNull(request.getParameter("applicant")),
                statusOrNull(request.getParameter("status")),
                dateOrNull(request.getParameter("filedFrom")),
                dateOrNull(request.getParameter("filedTo")));
    }

    private static String blankToNull(String value) {
        return value == null || value.isEmpty() ? null : value;
    }

    private static Status statusOrNull(String value) {
        if (blankToNull(value) == null) {
            return null;
        }
        try {
            return Status.valueOf(value);
        } catch (IllegalArgumentException e) {
            return null;
        }
    }

    private static LocalDate dateOrNull(String value) {
        if (blankToNull(value) == null) {
            return null;
        }
        try {
            return LocalDate.parse(value);
        } catch (DateTimeParseException e) {
            return null;
        }
    }

    private static String pathOf(HttpServletRequest request) {
        return request.getPathInfo() == null ? "" : request.getPathInfo();
    }

    private static Map<String, Object> toJson(Dossier dossier) {
        Map<String, Object> json = new LinkedHashMap<String, Object>();
        json.put("number", dossier.getNumber());
        json.put("applicant", dossier.getApplicant());
        json.put("subject", dossier.getSubject());
        json.put("status", dossier.getStatus().name());
        json.put("filedOn", dossier.getFiledOn().toString());
        json.put("submittedOn", dossier.getSubmittedOn() == null ? null : dossier.getSubmittedOn().toString());
        return json;
    }

    private static void writeError(HttpServletResponse response, int status, String message) throws IOException {
        Map<String, Object> json = new LinkedHashMap<String, Object>();
        json.put("error", message);
        writeJson(response, status, json);
    }

    private static void writeJson(HttpServletResponse response, int status, Object json) throws IOException {
        response.setStatus(status);
        response.setContentType("application/json;charset=UTF-8");
        JSON.writeValue(response.getOutputStream(), json);
    }
}
package fr.mairie.dossiers.service;

import fr.mairie.dossiers.model.Dossier;
import fr.mairie.dossiers.model.SearchCriteria;
import fr.mairie.dossiers.model.Status;

import java.time.Clock;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;

/**
 * Service métier des dossiers : seul endroit où vivent les règles métier.
 * Les écrans et l'API interne passent par lui.
 */
public class DossierService {

    private final List<Dossier> dossiers;
    private final Clock clock;

    /** @param clock horloge figée : toute date de remise en provient */
    public DossierService(List<Dossier> dossiers, Clock clock) {
        this.dossiers = new ArrayList<Dossier>(dossiers);
        this.clock = clock;
    }

    /** Dossiers qui satisfont tous les critères, triés par numéro, sans pagination. */
    public synchronized List<Dossier> search(SearchCriteria criteria) {
        List<Dossier> results = new ArrayList<Dossier>();
        for (Dossier dossier : dossiers) {
            if (matches(dossier, criteria)) {
                results.add(dossier);
            }
        }
        results.sort(Comparator.comparing(Dossier::getNumber));
        return results;
    }

    /** Le dossier de ce numéro. */
    public synchronized Dossier read(String number) {
        return dossiers.get(indexOf(number));
    }

    /**
     * Remplace le demandeur et l'objet. Le verrou du statut est appliqué ici,
     * pour les écrans comme pour l'API interne : un champ verrouillé ne peut
     * pas changer, même si la requête est forgée. Le renvoyer à l'identique
     * n'est pas une modification. Les valeurs ne sont pas validées : les
     * règles de saisie vivent seulement dans {@code validation.xml}.
     *
     * @throws UnknownDossierException si aucun dossier n'a ce numéro
     * @throws LockedFieldException si un champ verrouillé change
     */
    public synchronized Dossier update(String number, String applicant, String subject) {
        int index = indexOf(number);
        Dossier current = dossiers.get(index);
        if (current.getStatus().isApplicantLocked() && !current.getApplicant().equals(applicant)) {
            throw new LockedFieldException(number, "applicant");
        }
        if (current.getStatus().isSubjectLocked() && !current.getSubject().equals(subject)) {
            throw new LockedFieldException(number, "subject");
        }
        Dossier updated = current.withApplicantAndSubject(applicant, subject);
        dossiers.set(index, updated);
        return updated;
    }

    /**
     * Remet le dossier : il passe irréversiblement de {@code EN_INSTRUCTION} à
     * {@code REMIS}, daté du jour de l'horloge.
     *
     * @throws UnknownDossierException si aucun dossier n'a ce numéro
     * @throws RefusedSubmissionException si le dossier n'est pas {@code EN_INSTRUCTION}
     */
    public synchronized Dossier submit(String number) {
        int index = indexOf(number);
        Dossier current = dossiers.get(index);
        if (current.getStatus() != Status.EN_INSTRUCTION) {
            throw new RefusedSubmissionException(number, current.getStatus());
        }
        Dossier submitted = current.withSubmission(LocalDate.now(clock));
        dossiers.set(index, submitted);
        return submitted;
    }

    private int indexOf(String number) {
        for (int i = 0; i < dossiers.size(); i++) {
            if (dossiers.get(i).getNumber().equals(number)) {
                return i;
            }
        }
        throw new UnknownDossierException(number);
    }

    private static boolean matches(Dossier dossier, SearchCriteria criteria) {
        if (criteria.getNumber() != null && !criteria.getNumber().equals(dossier.getNumber())) {
            return false;
        }
        if (criteria.getApplicant() != null
                && !dossier.getApplicant().toLowerCase(Locale.ROOT)
                        .contains(criteria.getApplicant().toLowerCase(Locale.ROOT))) {
            return false;
        }
        if (criteria.getStatus() != null && criteria.getStatus() != dossier.getStatus()) {
            return false;
        }
        if (criteria.getFiledFrom() != null && dossier.getFiledOn().isBefore(criteria.getFiledFrom())) {
            return false;
        }
        if (criteria.getFiledTo() != null && dossier.getFiledOn().isAfter(criteria.getFiledTo())) {
            return false;
        }
        return true;
    }
}
